import collections,datetime,gzip,hashlib,json,re
from pathlib import Path
import numpy as np
H=Path.home();R=H/'dojo-data/kong-1107';RUNS=H/'dojo-data/integ-c6/runs2';M=json.loads((R/'manifest.json').read_text())
def pin(p):
 b=p.read_bytes();return {'path':str(p),'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()}
def jlines(p):return [json.loads(l) for l in p.read_text().splitlines() if l.strip()]
lane=[]
for p in (H/'dojo-integ-c6-state').glob('lane2_heavy*.log'):
 for l in p.read_text().splitlines():
  if ' done ' in l:lane.append((p.name,l))
res={'created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'manifest':pin(R/'manifest.json'),'route_amendment':'74d9ed80','panels':{}}
for panel,suffix,model in [('Sonnet primary','__sonnet','claude/claude-sonnet-5-5'),('Luna supplementary','','cx/gpt-6-luna')]:
 rows=[]
 for m in M['schedule']:
  name=m['name']+suffix;d=RUNS/name;epfile=next(d.glob('*_episodes.jsonl'));e=next(x for x in reversed(jlines(epfile)) if x['layout_id']==m['id']);rp=next(d.glob(f'*_{m["id"]}_report.json.gz'));rep=json.load(gzip.open(rp,'rt'))
  cps=sorted(d.glob('agentic/call_*/calls.jsonl'));cs=[x for p in cps for x in jlines(p)]
  tps=sorted(d.glob('agentic/call_*/*/transcript.jsonl'));ts=[x for p in tps for x in jlines(p)]
  models=sorted({x.get('model') for x in cs});tm=sorted({x.get('model') for x in ts if x.get('event')=='start'});rm=sorted({x.get('model') for x in e.get('agentic',[]) if x.get('calls',0)>0})
  calls=sum(x.get('calls',0) for x in cs);usage={k:sum(x.get('tokens',{}).get(k,0) for x in cs) for k in ['prompt','completion','reasoning','cache_read']}
  eu={k:sum(x.get('tokens',{}).get(k,0) for x in e.get('agentic',[])) for k in usage}
  cfgdiff={k:{'expected':v,'actual':rep.get('config',{}).get(k)} for k,v in m['runtime'].items() if rep.get('config',{}).get(k)!=v}
  errors=[x.get('error') for x in ts if x.get('event')=='reply' and x.get('error')]
  logs=[p for p in [d/'perception_service.log',d/'integ_eval.log',RUNS/(name+'.log')] if p.exists()]
  transport=[{'path':str(p),'line':l[:500]} for p in logs for l in p.read_text(errors='replace').splitlines() if re.search(r'(?i)(HTTP[^\n]{0,35}\b429\b|too many requests|rate.?limit|retrying|retry attempt|transport.?error)',l)]
  done=[{'log':pn,'line':l} for pn,l in lane if re.search(r'done\s+'+re.escape(name)+r'\s',l)]
  rows.append({'name':name,'task':m['task'],'block':m['block'],'id':m['id'],'arm':m['arm'],'score':100*e['score'],'success':e['success'],'category':e.get('category'),'time_capped':e.get('time_capped'),'steps':e.get('steps_used'),'wall_s':e.get('wall_s'),'reported_code_model':(e.get('code') or {}).get('model'),'call_log_models':models,'transcript_models':tm,'report_agentic_models':rm,'route_verified':models==tm==rm==[model],'logical_calls':calls,'transcript_reply_count':sum(x.get('event')=='reply' for x in ts),'usage':usage,'usage_matches_episode':usage==eu,'logical_calls_match_episode':calls==sum(x.get('calls',0) for x in e.get('agentic',[])),'config_diffs':cfgdiff,'vocabulary_matches':rep.get('vocabulary')==m['task'],'reply_errors':errors,'call_log_errors':[x['errors'] for x in cs if x.get('errors')],'transport_log_matches':transport,'completion':done,'pins':[pin(p) for p in [epfile,rp,*cps,*tps,*logs]]})
 cells=[]
 for task in ['make_kong','imitate_sorting_sequence','stack_blocks']:
  rr=[r for r in rows if r['task']==task];pairs=collections.defaultdict(dict)
  for x in rr:pairs[(x['block'],x['id'])][x['arm']]=x
  assert all(set(p)=={'A','B'} for p in pairs.values())
  ps=[{'block':b,'id':i,'A':p['A']['score'],'B':p['B']['score'],'delta':p['B']['score']-p['A']['score'],'A_success':p['A']['success'],'B_success':p['B']['success']} for (b,i),p in sorted(pairs.items())]
  a=np.array([p['A'] for p in ps]);b=np.array([p['B'] for p in ps]);delta=b-a;n=len(ps);rng=np.random.default_rng(0);ci=np.percentile(delta[rng.integers(0,n,(10000,n))].mean(axis=1),[2.5,97.5]).tolist()
  w=int(sum(delta>=10-1e-9));l=int(sum(delta<=-10+1e-9));sw=sum(p['B_success'] and not p['A_success'] for p in ps);sl=sum(p['A_success'] and not p['B_success'] for p in ps)
  checks={'complete':n==(10 if task=='make_kong' else 5),'delta':bool(delta.mean()>=(5 if task=='make_kong' else -5)-1e-9)}
  if task=='make_kong':checks.update(score_ratio=w>=2*l,score_net=w-l>=2)
  else:checks['success_flip_guard']=sl<=sw
  cells.append({'task':task,'n':n,'A_mean':float(a.mean()),'B_mean':float(b.mean()),'delta':float(delta.mean()),'A_sd':float(a.std(ddof=1)),'B_sd':float(b.std(ddof=1)),'delta_sd':float(delta.std(ddof=1)),'paired_bootstrap95':ci,'score_wins':w,'score_losses':l,'score_ties':n-w-l,'success_wins':sw,'success_losses':sl,'A_successes':sum(p['A_success'] for p in ps),'B_successes':sum(p['B_success'] for p in ps),'checks':checks,'score_rule_pass':all(checks.values()),'pairs':ps})
 out={'model':model,'rows':rows,'cells':cells,'logical_calls':sum(r['logical_calls'] for r in rows),'usage':{k:sum(r['usage'][k] for r in rows) for k in usage},'route_violations':[r['name'] for r in rows if not r['route_verified']],'config_mismatches':[r['name'] for r in rows if r['config_diffs'] or not r['vocabulary_matches']],'usage_mismatches':[r['name'] for r in rows if not r['usage_matches_episode'] or not r['logical_calls_match_episode']],'policy_time_caps':[r['name'] for r in rows if r['time_capped'] or r['category']=='time_cap'],'reply_errors':[r['name'] for r in rows if r['reply_errors'] or r['call_log_errors']],'transport_log_matches':[r['name'] for r in rows if r['transport_log_matches']],'camera_score_gate_pass':all(c['score_rule_pass'] for c in cells),'summed_wall_s':sum(r['wall_s'] for r in rows)}
 res['panels'][panel]=out
res['bootstrap']={'method':'percentile, paired-layout resampling independently per cell','resamples':10000,'rng':'numpy.default_rng(0), reset per cell','confidence':0.95,'gate':False}
res['transport_observability']='Logical calls/replies and surfaced errors/logged 429 observable; recovered HTTP attempt counters/status dropped by OmniChat, actual transient retries not recoverable. No new camera calls.'
res['source_pin_note']='Lane logs append: verify the first bytes bytes against the captured sha256; completed row source files are immutable.'
res['lane_log_pins']=[pin(p) for p in (H/'dojo-integ-c6-state').glob('lane2_heavy*.log')]
res['analysis_script']=pin(Path(__file__))
(R/'verdict.json').write_text(json.dumps(res,indent=2)+'\n')
for k,p in res['panels'].items():
 print(k,{q:p[q] for q in ['logical_calls','usage','route_violations','config_mismatches','usage_mismatches','policy_time_caps','reply_errors','transport_log_matches','camera_score_gate_pass','summed_wall_s']})
 for c in p['cells']:print({k:v for k,v in c.items() if k!='pairs'})
